const roles=['yellow','king','ninja','wizard'],names={yellow:'金帽兔',king:'國王兔',ninja:'忍者兔',wizard:'巫師兔'},points=[37000,29000,21000,13000],net=[1200,400,-400,-1200];
function show(role){if(!roles.includes(role))role='yellow';const image=document.querySelector('#champion');image.src=role==='yellow'?'/art/results/yellow-presentation.png':'/art/ribbon-v2/'+role+'-character.png';image.dataset.role=role;document.querySelector('#winnerName').textContent=names[role];document.querySelector('#standings').replaceChildren(...roles.map((_,i)=>{const character=roles[(roles.indexOf(role)+i)%4],li=document.createElement('li');li.innerHTML='<span class="rank">'+(i+1)+'</span><img class="avatar" src="/art/results/'+character+'-avatar.png" alt=""><span class="person">'+names[character]+'<small>'+(i===0?'本場冠軍':'對局玩家')+'</small></span><strong class="points">'+points[i].toLocaleString()+'</strong><span class="net '+(net[i]>0?'positive':'negative')+'">'+(net[i]>0?'+':'')+net[i].toLocaleString()+'</span>';return li}));document.querySelectorAll('[data-role]').forEach(b=>{if(b.tagName==='BUTTON')b.setAttribute('aria-pressed',String(b.dataset.role===role))});const url=new URL(location.href);url.searchParams.set('role',role);history.replaceState(null,'',url)}
document.querySelectorAll('.role-switch button').forEach(b=>b.onclick=()=>show(b.dataset.role));const resize=()=>document.querySelector('.canvas').style.transform='scale('+Math.min(innerWidth/1125,innerHeight/634)+')';addEventListener('resize',resize);resize();show(new URLSearchParams(location.search).get('role'));
for(const id of ['back','again'])document.getElementById(id).onclick=()=>document.querySelector('#notice').textContent='這是設計預覽，沒有變更牌局或錢包。';
